import inspect
from typing import ForwardRef, Any, Callable, Dict
from fastapi.dependencies.utils import get_typed_signature, get_typed_return_annotation

# Simulate two different modules
module_a_globals = {}
class B:
    pass
module_a_globals['B'] = B

def original_func(x: 'B') -> 'B':
    return x

original_func.__globals__ = module_a_globals

def wrapper(func):
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    wrapped.__wrapped__ = func
    # functools.wraps would do this:
    wrapped.__annotations__ = func.__annotations__
    return wrapped

module_b_globals = {}
wrapped_func = wrapper(original_func)
wrapped_func.__globals__ = module_b_globals

def test_get_typed_signature():
    print("Testing get_typed_signature...")
    sig = get_typed_signature(wrapped_func)
    for name, param in sig.parameters.items():
        print(f"Parameter {name}: {param.annotation}")
        if param.annotation is not B:
            raise AssertionError(f"Parameter {name} annotation should be B, got {param.annotation}")

def test_get_typed_return_annotation():
    print("Testing get_typed_return_annotation...")
    ret_ann = get_typed_return_annotation(wrapped_func)
    print(f"Return annotation: {ret_ann}")
    if ret_ann is not B:
        raise AssertionError(f"Return annotation should be B, got {ret_ann}")

